import type { CoreTag } from './analysis';

// ── 성향 근거의 정보량 (engine v4) ──────────────────────────────────────────────
// 같은 "지지"라도 흔한 근거와 드문 근거는 무게가 다르다. 별자리·점성술은 태양·달·상승을 합쳐 '창의적'을
// 77% 확률로 내놓으므로, 그 소스가 '창의적'을 지지한다는 사실은 이 사람을 거의 구별하지 못한다.
// 반대로 MBTI가 '직관적'을 내놓는 경우는 13%라 훨씬 많은 정보를 준다.
// 근거 하나의 정보량 = -ln P(소스가 그 성향을 냄). 성향 점수 = 지지 소스 정보량의 합.
// P는 scripts/derive-trait-base-rates.ts로 균등한 합성 입력에서 구한 고정값이다(인구 통계가 아님).
// 결정적이며, 이 표를 바꾸면 engineVersion을 올린다.

export const TRAIT_BASE_RATES: Readonly<Record<string, Readonly<Partial<Record<CoreTag, number>>>>> = {
  // generated by scripts/derive-trait-base-rates.ts (N=6000)
  saju: { 창의적: 0.560, 분석적: 0.273, 감성적: 0.000, 실용적: 0.278, 사교적: 0.000, 독립적: 0.258, 직관적: 0.468, 체계적: 0.118, 열정적: 0.377, 포용적: 0.359 },
  'western-astrology': { 창의적: 0.770, 분석적: 0.361, 감성적: 0.496, 실용적: 0.601, 사교적: 0.467, 독립적: 0.694, 직관적: 0.595, 체계적: 0.489, 열정적: 0.588, 포용적: 0.341 },
  mbti: { 창의적: 0.314, 분석적: 0.388, 감성적: 0.238, 실용적: 0.300, 사교적: 0.371, 독립적: 0.191, 직관적: 0.129, 체계적: 0.389, 열정적: 0.381, 포용적: 0.300 },
  'blood-type': { 창의적: 0.497, 분석적: 0.245, 감성적: 0.250, 실용적: 0.503, 사교적: 0.253, 독립적: 0.497, 직관적: 0.252, 체계적: 0.250, 열정적: 0.253, 포용적: 0.000 },
};
// 손금은 모델이 영역마다 0~2개 후보를 내고 상위 3개만 쓰므로 10개 성향 중 약 3개 — 고정 0.3으로 둔다.
const PALM_BASE_RATE = 0.3;
// 점수 동률일 때 쓰는 고정 순서 (CoreTag 정의 순서) — 입력·trace 순서와 무관한 결정성
export const TRAIT_ORDER: readonly CoreTag[] = ['창의적', '분석적', '감성적', '실용적', '사교적', '독립적', '직관적', '체계적', '열정적', '포용적'];
const MIN_RATE = 0.02; // 표본에 없던 조합도 무한대 정보량이 되지 않게

export function evidenceInformation(source: string, trait: CoreTag): number {
  const p = source === 'palm' ? PALM_BASE_RATE : TRAIT_BASE_RATES[source]?.[trait] ?? 0.5;
  return -Math.log(Math.max(p, MIN_RATE));
}

export function traitScore(trait: CoreTag, sources: readonly string[]): number {
  return sources.reduce((s, src) => s + evidenceInformation(src, trait), 0);
}

// 사용자 표시용 구분. 두 소스가 모두 흔한 근거(각 P≈0.5)로 겹치면 약 1.4, 드문 근거가 섞이면 3 이상이 된다.
export type TraitDistinctiveness = 'common' | 'notable' | 'distinctive';
export function distinctivenessOf(score: number): TraitDistinctiveness {
  if (score >= 3.2) return 'distinctive';
  if (score >= 2.0) return 'notable';
  return 'common';
}
